css:
:where(.wtyg-map-site_food_system) *{box-sizing:border-box;margin:0;padding:0}
:where(.wtyg-map-site_food_system),:where(.wtyg-map-site_food_system){height:100%}
:where(.wtyg-map-site_food_system){font-family:'Archivo',sans-serif;background:#f4f3ef;color:#222;overflow:hidden;-webkit-font-smoothing:antialiased}
:where(.wtyg-map-site_food_system) .app{display:flex;flex-direction:column;height:100vh}
:where(.wtyg-map-site_food_system) .topbar{display:flex;align-items:center;gap:16px;padding:0 16px;height:58px;flex-shrink:0;background:#111;color:#fff;border-bottom:3px solid #e0a93a;z-index:30}
:where(.wtyg-map-site_food_system) .title{display:flex;flex-direction:column;line-height:1;flex-shrink:0}
:where(.wtyg-map-site_food_system) .title .t{font-family:'Anton',sans-serif;font-size:20px;letter-spacing:.02em;text-transform:uppercase}
:where(.wtyg-map-site_food_system) .title .t span{color:#e0a93a}
:where(.wtyg-map-site_food_system) .title .s{font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:#9a9a9a;margin-top:4px;font-weight:600}
:where(.wtyg-map-site_food_system) .searchwrap{position:relative;flex:1;max-width:330px}
:where(.wtyg-map-site_food_system) .searchwrap svg{position:absolute;left:13px;top:50%;transform:translateY(-50%);width:16px;height:16px;stroke:#888}
:where(.wtyg-map-site_food_system) :is([data-wtyg-id="search"],#wtyg-noid-search){width:100%;padding:9px 14px 9px 38px;border:1px solid #333;border-radius:9px;font-family:'Archivo';font-size:14px;color:#fff;background:#222;outline:none}
:where(.wtyg-map-site_food_system) :is([data-wtyg-id="search"],#wtyg-noid-search)::placeholder{color:#888}
:where(.wtyg-map-site_food_system) :is([data-wtyg-id="search"],#wtyg-noid-search):focus{border-color:#e0a93a;box-shadow:0 0 0 3px rgba(224,169,58,.18)}
:where(.wtyg-map-site_food_system) .result{font-size:12px;color:#aaa;font-weight:600;white-space:nowrap;flex-shrink:0}
:where(.wtyg-map-site_food_system) .result b{color:#e0a93a}
:where(.wtyg-map-site_food_system) .tools{display:flex;gap:8px;flex-shrink:0}
:where(.wtyg-map-site_food_system) .tools button{font-family:'Archivo';font-weight:600;font-size:12px;color:#ddd;background:#222;border:1px solid #333;border-radius:8px;padding:8px 11px;cursor:pointer}
:where(.wtyg-map-site_food_system) .tools button:hover{border-color:#e0a93a;color:#fff}
:where(.wtyg-map-site_food_system) .panes{display:flex;flex-direction:row;flex:1;min-height:0}
:where(.wtyg-map-site_food_system) .pane{position:relative;min-width:0}
:where(.wtyg-map-site_food_system) .pane-top{flex:1.18;display:flex;flex-direction:column;background:#fff;border-right:2px solid #d9d6cf;min-width:0}
:where(.wtyg-map-site_food_system) .pane-map{flex:1}
:where(.wtyg-map-site_food_system) .tabbar{height:46px;flex-shrink:0;display:flex;align-items:center;gap:8px;background:#fafafa;border-bottom:1px solid #e8e6e0;padding:0 12px}
:where(.wtyg-map-site_food_system) .tab{display:flex;align-items:center;gap:7px;border:1.5px solid #e0ddd6;background:#fff;border-radius:999px;font-family:'Archivo';font-weight:700;font-size:12.5px;color:#777;padding:7px 14px;cursor:pointer;transition:.15s}
:where(.wtyg-map-site_food_system) .tab:hover{color:#333;border-color:#cfcbc2}
:where(.wtyg-map-site_food_system) .tab .ic{width:14px;height:14px;flex-shrink:0;stroke-width:2.2;fill:none}
:where(.wtyg-map-site_food_system) .tab.on{color:#fff;border-color:transparent}
:where(.wtyg-map-site_food_system) .tab.on.t-companies{background:#1f6fb2}
:where(.wtyg-map-site_food_system) .tab.on.t-financial{background:#2c3e50}
:where(.wtyg-map-site_food_system) .tab.on.t-lobby{background:#c2185b}
:where(.wtyg-map-site_food_system) .tab.on.t-ownership{background:#16a085}
:where(.wtyg-map-site_food_system) .tab.on.t-orbit{background:#3949ab}
:where(.wtyg-map-site_food_system) .tab.on.t-all{background:#111}
:where(.wtyg-map-site_food_system) .stage{flex:1;position:relative;min-height:0}
:where(.wtyg-map-site_food_system) :is([data-wtyg-id="netsvg"],#wtyg-noid-netsvg){width:100%;height:100%;display:block;cursor:grab;touch-action:none}
:where(.wtyg-map-site_food_system) :is([data-wtyg-id="netsvg"],#wtyg-noid-netsvg):active{cursor:grabbing}
:where(.wtyg-map-site_food_system) :is([data-wtyg-id="map"],#wtyg-noid-map){width:100%;height:100%;background:#0b1418}
:where(.wtyg-map-site_food_system) .guide{fill:none;stroke:#ececec;stroke-width:1.4;stroke-dasharray:2 6}
:where(.wtyg-map-site_food_system) .spine{fill:none;stroke:#d9d6cf;stroke-width:1.5;stroke-dasharray:3 5;opacity:.7}
:where(.wtyg-map-site_food_system) .ringlabel rect{fill:#fff;stroke:#e4e2dc;rx:6}
:where(.wtyg-map-site_food_system) .ringlabel text{font-family:'Anton',sans-serif;text-transform:uppercase;letter-spacing:.04em;dominant-baseline:middle}
:where(.wtyg-map-site_food_system) .tie{fill:none;stroke-opacity:0;transition:stroke-opacity .25s;pointer-events:none}
:where(.wtyg-map-site_food_system) .tie.show{stroke-opacity:.82}
:where(.wtyg-map-site_food_system) .tie.hot{stroke-opacity:1}
:where(.wtyg-map-site_food_system) .tie.cold{stroke-opacity:.06}
:where(.wtyg-map-site_food_system) .tie.dim{stroke-opacity:.14}
:where(.wtyg-map-site_food_system) .hub{cursor:pointer}
:where(.wtyg-map-site_food_system) .hub text.main{font-weight:800;text-anchor:middle;dominant-baseline:middle}
:where(.wtyg-map-site_food_system) .hub line.ul{stroke-width:3;stroke-linecap:round}
:where(.wtyg-map-site_food_system) .hub text.sub{font-weight:700;font-size:12px;letter-spacing:.02em;text-anchor:middle}
:where(.wtyg-map-site_food_system) .ownernode text.main{font-family:'Anton',sans-serif;font-weight:400}
:where(.wtyg-map-site_food_system) .bb text{font-size:11.5px;font-weight:600;fill:#333;text-anchor:middle;dominant-baseline:middle;pointer-events:none}
:where(.wtyg-map-site_food_system) .bb rect{fill:#fff;rx:5}
:where(.wtyg-map-site_food_system) .bl{stroke-opacity:.5;stroke-width:1.2}
:where(.wtyg-map-site_food_system) .core text{font-family:'Anton',sans-serif;fill:#111;text-anchor:middle;dominant-baseline:middle}
:where(.wtyg-map-site_food_system) .core circle{fill:#fff;stroke:#111;stroke-width:2.5}
:where(.wtyg-map-site_food_system) .faded{opacity:.12;transition:opacity .25s}
:where(.wtyg-map-site_food_system) .leaflet-popup-content-wrapper{border-radius:9px}
:where(.wtyg-map-site_food_system) .leaflet-popup-content{margin:11px 13px;font-family:'Archivo';font-size:12.5px;line-height:1.45}
:where(.wtyg-map-site_food_system) .pop-n{font-weight:800;font-size:14px}
:where(.wtyg-map-site_food_system) .pop-meta{color:#666;margin-top:3px}
:where(.wtyg-map-site_food_system) .badge{position:absolute;z-index:500;background:rgba(255,255,255,.96);border:1px solid #e4e2dc;border-radius:8px;font-size:11.5px;color:#666;padding:8px 12px;line-height:1.45;max-width:300px;max-height:40%;overflow:auto}
:where(.wtyg-map-site_food_system) .badge.tl{top:10px;left:10px}
:where(.wtyg-map-site_food_system) .badge b{color:#333}
:where(.wtyg-map-site_food_system) .mapbadge{position:absolute;z-index:500;top:10px;left:10px;background:rgba(10,20,24,.82);color:#cfe;border:1px solid #1e3a44;border-radius:8px;font-size:11px;padding:7px 11px;max-width:300px;line-height:1.4}
:where(.wtyg-map-site_food_system) .mapbadge b{color:#fff}
:where(.wtyg-map-site_food_system) .legend{position:absolute;z-index:500;top:10px;right:10px;background:rgba(255,255,255,.96);border:1px solid #e4e2dc;border-radius:9px;padding:9px 11px;box-shadow:0 4px 16px rgba(0,0,0,.06);max-height:calc(100% - 20px);overflow:auto;min-width:140px}
:where(.wtyg-map-site_food_system) .legend .lh{font-size:9px;letter-spacing:.1em;text-transform:uppercase;color:#aaa;font-weight:800;margin-bottom:6px}
:where(.wtyg-map-site_food_system) .legend .row{display:flex;align-items:center;gap:7px;font-size:12px;font-weight:600;color:#444;cursor:pointer;padding:3px 5px;border-radius:5px}
:where(.wtyg-map-site_food_system) .legend .row:hover{background:#f3f1ec}
:where(.wtyg-map-site_food_system) .legend .row.off{opacity:.3}
:where(.wtyg-map-site_food_system) .legend .row.sel{background:#f0ede7}
:where(.wtyg-map-site_food_system) .legend .sw{width:12px;height:12px;border-radius:3px;flex-shrink:0}
:where(.wtyg-map-site_food_system) .legend .ln{width:16px;height:0;border-top:3px solid;flex-shrink:0;border-radius:2px}
:where(.wtyg-map-site_food_system) .legend .ct{margin-left:auto;color:#bbb;font-size:10px;font-weight:700}
:where(.wtyg-map-site_food_system) .info{position:absolute;z-index:500;bottom:10px;left:10px;width:290px;max-height:calc(100% - 20px);overflow:auto;background:rgba(255,255,255,.97);border:1px solid #e4e2dc;border-left:4px solid #ccc;border-radius:10px;padding:11px 13px;box-shadow:0 6px 22px rgba(0,0,0,.08)}
:where(.wtyg-map-site_food_system) .info .iname{font-weight:800;font-size:15px;line-height:1.1}
:where(.wtyg-map-site_food_system) .info .icity{font-size:11px;color:#999;font-weight:600;margin-top:2px}
:where(.wtyg-map-site_food_system) .info .idesc{font-size:11.5px;color:#555;margin-top:7px;line-height:1.4;min-height:28px}
:where(.wtyg-map-site_food_system) .info .imetrics{display:flex;gap:14px;margin-top:8px}
:where(.wtyg-map-site_food_system) .info .imetrics .m .v{font-family:'Anton',sans-serif;font-size:16px;line-height:1}
:where(.wtyg-map-site_food_system) .info .imetrics .m .k{font-size:8px;letter-spacing:.07em;text-transform:uppercase;color:#aaa;font-weight:700;margin-top:3px}
:where(.wtyg-map-site_food_system) .iown{margin-top:8px;font-size:11px;color:#444}
:where(.wtyg-map-site_food_system) .iown b{color:#111}
:where(.wtyg-map-site_food_system) .irels{margin-top:9px;border-top:1px solid #eee;padding-top:7px}
:where(.wtyg-map-site_food_system) .relhd{font-size:8px;letter-spacing:.05em;text-transform:uppercase;color:#aaa;font-weight:800;margin-bottom:5px}
:where(.wtyg-map-site_food_system) .relrow{display:flex;align-items:center;gap:5px;margin:3px 0}
:where(.wtyg-map-site_food_system) .reldot{width:8px;height:8px;border-radius:2px;flex-shrink:0}
:where(.wtyg-map-site_food_system) .reln{font-size:10.5px;font-weight:700;color:#333;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex:0 0 76px}
:where(.wtyg-map-site_food_system) .reltier{font-size:8.5px;font-weight:800;flex:0 0 72px}
:where(.wtyg-map-site_food_system) .relbarwrap{flex:1;height:5px;background:#eee;border-radius:3px;overflow:hidden;min-width:18px}
:where(.wtyg-map-site_food_system) .relbar{height:100%;border-radius:3px}
:where(.wtyg-map-site_food_system) .ibarwrap{margin-top:8px}
:where(.wtyg-map-site_food_system) .ibarwrap .lbl{font-size:8.5px;letter-spacing:.05em;text-transform:uppercase;color:#aaa;font-weight:700;display:flex;justify-content:space-between}
:where(.wtyg-map-site_food_system) .ibar{height:7px;background:#eee;border-radius:4px;margin-top:3px;overflow:hidden}
:where(.wtyg-map-site_food_system) .ibar>div{height:100%;border-radius:4px;transition:width .4s}
@media(max-width:760px){:where(.wtyg-map-site_food_system) .result{display:none}
:where(.wtyg-map-site_food_system) .title .t{font-size:14px}
:where(.wtyg-map-site_food_system) .topbar{gap:8px;padding:0 8px}
:where(.wtyg-map-site_food_system) .info{width:188px}
:where(.wtyg-map-site_food_system) .legend{display:none}
:where(.wtyg-map-site_food_system) .tab{padding:6px 10px;font-size:11px}
:where(.wtyg-map-site_food_system) .panes{flex-direction:column}
:where(.wtyg-map-site_food_system) .pane-top{border-right:none;border-bottom:2px solid #d9d6cf}}
